// Generated by `npm run models` — each garment model's measurements, in metres,
// with the top of the garment at y = 0, centred in x, the front facing +z.

export type ModelBounds = {
  /** Overall size. */
  width: number;
  height: number;
  depth: number;
  /** Centre of the depth (z), between front and back. */
  midZ: number;
  /** Where a hanger's shoulders rest, and the top of the shoulders at the centre line. */
  shoulderX: number;
  shoulderY: number;
  neckY: number;
  /** Top of the neckline at the centre line, front and back. */
  collarFront: number;
  collarBack: number;
  /** Width of the torso across the chest: counts as the 20 in of a size M. */
  chest: number;
};

